async function run() {
  const today = dates.today();
  const from = dates.startOfDay(today, 0);
  const to = dates.addHours(from, 24);

  const events = await calendar.events({ from, to });

  const emails = await gmail.search({ query: "in:inbox is:unread", days: 1, unread: true, max: 20 });

  const importantEmails = [];
  for (const email of emails) {
    const res = await judge.important(email);
    if (res.p >= 0.5) importantEmails.push(email);
  }

  const weatherUrl = "https://api.open-meteo.com/v1/forecast?latitude=-23.55&longitude=-46.63&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=America%2FSao_Paulo&forecast_days=1";
  const weather = await http.getJSON(weatherUrl);
  const tMax = weather.daily.temperature_2m_max[0];
  const tMin = weather.daily.temperature_2m_min[0];
  const precip = weather.daily.precipitation_probability_max[0];

  const header = "Bom dia! Resumo de " + dates.format(from, "EEEE', ' dd'/'MM");

  let agendaLines;
  if (events.length === 0) {
    agendaLines = ["Nenhum evento agendado."];
  } else {
    agendaLines = events.map(function (ev) {
      if (ev.start.length <= 10) {
        return "• dia todo: " + ev.title;
      }
      return "• " + dates.format(ev.start, "HH:mm") + " " + ev.title;
    });
  }

  let emailLines;
  if (importantEmails.length === 0) {
    emailLines = ["Nenhum email importante."];
  } else {
    emailLines = importantEmails.map(function (e) {
      return "• " + e.from_name + ": " + e.subject;
    });
  }

  const weatherLine = "Tempo em São Paulo: " + tMin + "°C a " + tMax + "°C, " + precip + "% de chance de chuva.";

  const text =
    header +
    "\n\nAgenda:\n" +
    agendaLines.join("\n") +
    "\n\nEmails importantes:\n" +
    emailLines.join("\n") +
    "\n\n" +
    weatherLine;

  log(text);

  await telegram.send({ text });
}

async function run() {
  const today = dates.today();
  const windowEnd = dates.addDays(today, 7);

  const emails = await gmail.search({ query: "boleto OR fatura OR invoice OR vencimento", days: 30, max: 30 });

  const paidKeywords = [
    "pagamento confirmado",
    "recebemos o pagamento",
    "fatura paga",
    "pago com sucesso",
    "payment confirmed",
    "paid in full",
    "já paga"
  ];

  const bills = [];

  for (const email of emails) {
    const text = `${email.subject || ""} ${email.snippet || ""}`.toLowerCase();
    if (paidKeywords.some(k => text.includes(k))) continue;

    const due = dates.parse(email.snippet) || dates.parse(email.subject);
    if (!due) continue;

    if (dates.isBefore(due, today) || dates.isBefore(windowEnd, due)) continue;

    const amountText = money.find(email.snippet) || money.find(email.subject);
    const amount = amountText ? money.parse(amountText) : null;
    if (amount == null) continue;

    bills.push({ due, amount, subject: (email.subject || "").trim() });
  }

  if (bills.length === 0) {
    log("Nenhuma conta vencendo nos próximos 7 dias.");
    return;
  }

  bills.sort((a, b) => (a.due < b.due ? -1 : a.due > b.due ? 1 : 0));

  let total = 0;
  const lines = bills.map(b => {
    total += b.amount;
    return `• ${dates.format(b.due, "dd/MM")} — ${b.subject}: ${money.format(b.amount, "BRL")}`;
  });

  const text = `Contas vencendo nos próximos 7 dias:\n\n${lines.join("\n")}\n\nTotal: ${money.format(total, "BRL")}`;

  await telegram.send({ text });
}

async function run() {
  const emails = await gmail.search({
    query: "boleto OR fatura OR invoice OR vencimento",
    days: 30,
    max: 30
  });

  const today = dates.today();
  const limit = dates.addDays(today, 7);

  const bills = [];

  for (const e of emails) {
    const text = `${e.subject || ""} ${e.snippet || ""}`;
    const dueDate = dates.parse(text);
    if (!dueDate) continue;

    // must be due today or within the next 7 days (inclusive)
    if (dates.isBefore(dueDate, today)) continue;
    if (dates.isBefore(limit, dueDate)) continue;

    const amountText = money.find(text);
    if (!amountText) continue;

    bills.push({
      dueDate,
      amountText,
      amountValue: money.parse(amountText),
      subject: e.subject,
      from_name: e.from_name
    });
  }

  if (bills.length === 0) {
    return;
  }

  bills.sort((a, b) => (dates.isBefore(a.dueDate, b.dueDate) ? -1 : 1));

  let total = 0;
  const lines = bills.map((b) => {
    if (typeof b.amountValue === "number") total += b.amountValue;
    return `• ${dates.format(b.dueDate, "dd/MM")} — ${b.subject} (${b.from_name}): ${b.amountText}`;
  });

  const text = `Contas vencendo nos próximos 7 dias:\n\n${lines.join("\n")}\n\nTotal: ${money.format(total, "BRL")}`;

  await telegram.send({ text });
}

async function run() {
  const emails = await gmail.search({ query: "in:inbox is:unread", days: 2, unread: true, max: 50 });

  let archivedCount = 0;
  const archivedNames = [];

  for (const email of emails) {
    const result = await judge.newsletter(email);
    if (result.p >= 0.5) {
      await gmail.archive({ id: email.id });
      archivedCount++;
      archivedNames.push(email.from_name || email.from);
    }
  }

  let text;
  if (archivedCount === 0) {
    text = "Inbox cleanup done: no newsletters or promos to archive tonight.";
  } else {
    const namesPart = archivedNames.length > 0 ? ` (${archivedNames.join(", ")})` : "";
    text = `Inbox cleanup done: archived ${archivedCount} newsletter${archivedCount === 1 ? "" : "s"}/promo${archivedCount === 1 ? "" : "s"}${namesPart}.`;
  }

  await telegram.send({ text });
  log(`Archived ${archivedCount} of ${emails.length} unread emails.`);
}

