    const senderName = email.from_name || email.from;
    const text = `📩 Novo email da chefe (${senderName}): "${email.subject}"`;

    await telegram.send({ text });
    await gmail.label({ id: email.id, label: notifiedLabel });
  }
}

async function run() {
  const from = dates.startOfDay(now(), 1);
  const to = dates.addDays(from, 7);

  const events = await calendar.events({ from, to });

  const blocks = [];
  for (let i = 0; i < 7; i++) {
    const dayStart = dates.addDays(from, i);
    const header = dates.format(dayStart, "EEE d/MM");

    const dayEvents = events
      .filter(e => dates.sameDay(e.start, dayStart))
      .slice()
      .sort((a, b) => (dates.isBefore(a.start, b.start) ? -1 : dates.isBefore(b.start, a.start) ? 1 : 0));

    const lines = [header];
    if (dayEvents.length === 0) {
      lines.push("• nothing scheduled");
    } else {
      for (const e of dayEvents) {
        const time = dates.format(e.start, "HH:mm");
        lines.push(`• ${time} ${e.title}`);
      }
    }
    blocks.push(lines.join("\n"));
  }

  const text = "Your week ahead:\n\n" + blocks.join("\n\n");

  log(`Sending week-ahead agenda covering ${from} to ${to}`);
  await telegram.send({ text });
}

async function run() {
  const emails = await gmail.search({
    query: 'tracking OR rastreio OR "código de rastreamento" OR shipped OR enviado',
    days: 14,
    max: 20
  });

  // Generic international postal tracking code format (UPU S10-style):
  // 2 letters, 9 digits, 2 letters.
  const codeRegex = /\b[A-Z]{2}\d{9}[A-Z]{2}\b/g;

  const packages = new Map(); // code -> { fromName }
  for (const email of emails || []) {
    const text = `${email.subject || ''} ${email.snippet || ''}`;
    const matches = text.match(codeRegex);
    if (!matches) continue;
    for (const code of matches) {
      if (!packages.has(code)) {
        packages.set(code, { fromName: email.from_name || email.from || '' });
      }
    }
  }

  if (packages.size === 0) {
    log('No shipping emails with a tracking code found.');
    return;
  }

  const lines = [];
  for (const [code, info] of packages) {
    const url = `https://api.trackingmore.example/v1/track?code=${code}`;
    const result = await http.getJSON(url);
    if (!result) continue;

    const status = (result.status || '').replace(/_/g, ' ');
    let line = `• ${code}`;
    if (info.fromName) line += ` (${info.fromName})`;
    if (status) line += `: ${status}`;
    if (result.last_event) line += ` — ${result.last_event}`;
    if (result.eta && result.status !== 'delivered') line += `, ETA ${result.eta}`;
    lines.push(line);
  }

  if (lines.length === 0) {
    log('No tracking results returned.');
    return;
  }

  const text = `📦 Package status\n\n${lines.join('\n')}`;
  await telegram.send({ text });
}

async function run() {
  const from = dates.startOfDay(now(), 1);
  const to = dates.startOfDay(now(), 2);
  const events = await calendar.events({ from, to });

  const meetings = events
    .filter(e => Array.isArray(e.attendees) && e.attendees.length > 0)
    .sort((a, b) => (dates.isBefore(a.start, b.start) ? -1 : 1));

  if (meetings.length === 0) {
    log("Nenhuma reunião com convidados amanhã.");
    return;
  }

  const ownerEmail = "owner@example.com";
  const sections = [];

  for (const meeting of meetings) {
    const uniqueAttendees = [...new Set(meeting.attendees)].filter(
      email => email && email.toLowerCase() !== ownerEmail
    );

    const attendeeLines = [];
    for (const email of uniqueAttendees) {
      const emails = await gmail.search({ query: `from:${email}`, days: 14, max: 5 });
      if (!emails || emails.length === 0) continue;
      const name = emails[0].from_name || email;
      const subjects = emails
        .map(m => `"${m.subject}"${m.replied ? "" : " (sem resposta)"}`)
        .join("; ");
      attendeeLines.push(`• ${name} — ${subjects}`);
    }

    if (attendeeLines.length === 0) {
      attendeeLines.push("• Sem emails recentes dos participantes");
    }

    const timeStr = dates.format(meeting.start, "HH:mm");
    sections.push(`${timeStr} ${meeting.title}\n${attendeeLines.join("\n")}`);
  }

  const dateStr = dates.format(from, "dd/MM");
  const text = `Preparação para amanhã (${dateStr})\n\n${sections.join("\n\n")}`;

  await telegram.send({ text });
}

