async function run() {
  const THRESHOLD = 5.40;
  const url = "https://api.exchangerate.example/v1/latest?base=USD&symbols=BRL";
  const data = await http.getJSON(url);

  if (!data || !data.rates || typeof data.rates.BRL !== "number") {
    log("No valid BRL rate found in response");
    return;
  }

  const rate = data.rates.BRL;
  log("Current USD->BRL rate: " + rate);

  if (rate > THRESHOLD) {
    const formatted = rate.toFixed(2);
    await telegram.send({ text: "💵 USD→BRL is at " + formatted + ", above your " + THRESHOLD.toFixed(2) + " threshold." });
  } else {
    log("Rate is at or below threshold, no alert sent.");
  }
}

async function run() {
  const cutoff = dates.addDays(now(), -3);

  const emails = await gmail.search({ query: "in:inbox -from:me", days: 30, max: 50 });

  // Keep only unreplied emails older than 3 days.
  const candidates = emails.filter(e => !e.replied && dates.isBefore(e.date, cutoff));

  const results = [];
  for (const e of candidates) {
    const j = await judge.needs_reply(e);
    if (j.p >= 0.5) results.push(e);
  }

  if (results.length === 0) {
    log("No emails waiting on a reply.");
    return;
  }

  // Oldest first.
  results.sort((a, b) => (dates.isBefore(a.date, b.date) ? -1 : 1));

  const lines = results.map(e => `• ${e.from_name} — "${e.subject}" (since ${dates.format(e.date, "MMM d")})`);
  const text = `Waiting on your reply (3+ days):\n\n${lines.join("\n")}`;

  await telegram.send({ text });
}

async function run() {
  const start = dates.today();
  const tomorrow = dates.addDays(start, 1);
  const end = dates.addDays(start, 2);

  const events = await calendar.events({ from: start, to: end });

  const todayNames = [];
  const tomorrowNames = [];

  for (const e of events) {
    if (e.calendar !== "Birthdays") continue;
    let name = e.title.replace(/^Anivers[áa]rio de\s*/i, "").trim();
    if (!name) name = e.title;
    if (dates.sameDay(e.start, start)) {
      todayNames.push(name);
    } else if (dates.sameDay(e.start, tomorrow)) {
      tomorrowNames.push(name);
    }
  }

  if (todayNames.length === 0 && tomorrowNames.length === 0) {
    log("Nenhum aniversário hoje ou amanhã.");
    return;
  }

  const todayLabel = dates.format(start, "dd/MM");
  const tomorrowLabel = dates.format(tomorrow, "dd/MM");

  const lines = ["🎂 Aniversários", ""];
  if (todayNames.length > 0) {
    lines.push(`Hoje (${todayLabel}): ${todayNames.join(", ")}`);
  }
  if (tomorrowNames.length > 0) {
    lines.push(`Amanhã (${tomorrowLabel}): ${tomorrowNames.join(", ")}`);
  }

  await telegram.send({ text: lines.join("\n") });
}
